const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts with no items and no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
    });
  });

  describe('addItem', () => {
    it('adds a new line item with its name, price and quantity', () => {
      cart.addItem('apple', 1.5, 4);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 4 }]);
    });

    it('merges quantity into the existing line when the same name is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 5 }]);
    });

    it('keeps the original unit price when merging a repeated name', () => {
      cart.addItem('apple', 1.5, 1);
      cart.addItem('apple', 9.99, 1);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('defaults quantity to 1 when omitted', () => {
      cart.addItem('apple', 2);
      assert.equal(cart.items[0].quantity, 1);
    });

    it('accepts a zero price for free items', () => {
      cart.addItem('sticker', 0, 3);
      assert.deepEqual(cart.items, [{ name: 'sticker', price: 0, quantity: 3 }]);
    });

    it('treats names as case-sensitive distinct items', () => {
      cart.addItem('Apple', 1, 1);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('bug 1: rejects a negative price with RangeError and leaves the cart empty', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), {
        name: 'RangeError',
        message: /price/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: rejects a negative quantity with RangeError and leaves the cart empty', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), {
        name: 'RangeError',
        message: /quantity/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: rejects a negative quantity that would shrink an existing line', () => {
      cart.addItem('apple', 1, 5);
      assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
      assert.deepEqual(cart.items, []);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
    });

    it('rejects a non-finite price', () => {
      assert.throws(() => cart.addItem('apple', Infinity, 1), RangeError);
      assert.throws(() => cart.addItem('apple', -Infinity, 1), RangeError);
    });

    for (const [label, badValue] of [
      ['a numeric string', '10'],
      ['NaN', NaN],
      ['null', null],
      ['an object', {}],
      ['a bigint', 10n],
    ]) {
      it(`rejects ${label} as price with TypeError`, () => {
        assert.throws(() => cart.addItem('apple', badValue, 1), TypeError);
        assert.deepEqual(cart.items, []);
      });

      it(`rejects ${label} as quantity with TypeError`, () => {
        assert.throws(() => cart.addItem('apple', 1, badValue), TypeError);
        assert.deepEqual(cart.items, []);
      });
    }

    it('rejects a missing or non-string name with TypeError', () => {
      assert.throws(() => cart.addItem(undefined, 1, 1), TypeError);
      assert.throws(() => cart.addItem(42, 1, 1), TypeError);
      assert.throws(() => cart.addItem(null, 1, 1), TypeError);
    });

    it('rejects an empty or whitespace-only name with RangeError', () => {
      assert.throws(() => cart.addItem('', 1, 1), RangeError);
      assert.throws(() => cart.addItem('   ', 1, 1), RangeError);
      assert.deepEqual(cart.items, []);
    });
  });

  describe('removeItem', () => {
    beforeEach(() => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 2, 3);
      cart.addItem('cherry', 3, 1);
    });

    it('bug 2: removes only the named item and keeps the others', () => {
      cart.removeItem('banana');
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['apple', 'cherry'],
      );
    });

    it('bug 2: does not rename the remaining items to the removed name', () => {
      cart.removeItem('apple');
      assert.deepEqual(cart.items, [
        { name: 'banana', price: 2, quantity: 3 },
        { name: 'cherry', price: 3, quantity: 1 },
      ]);
    });

    it('bug 2: returns false and leaves the cart untouched when the item is missing', () => {
      const before = structuredClone(cart.items);
      assert.equal(cart.removeItem('durian'), false);
      assert.deepEqual(cart.items, before);
    });

    it('returns true when an item was removed', () => {
      assert.equal(cart.removeItem('apple'), true);
    });

    it('removes the whole line regardless of its quantity', () => {
      cart.removeItem('banana');
      assert.equal(
        cart.items.some((i) => i.name === 'banana'),
        false,
      );
      assert.equal(cart.getTotal(), 1 * 2 + 3 * 1);
    });

    it('returns false the second time the same item is removed', () => {
      assert.equal(cart.removeItem('cherry'), true);
      assert.equal(cart.removeItem('cherry'), false);
      assert.equal(cart.getItemCount(), 2);
    });

    it('returns false on an empty cart', () => {
      const empty = new ShoppingCart();
      assert.equal(empty.removeItem('apple'), false);
      assert.deepEqual(empty.items, []);
    });

    it('matches names exactly (case-sensitive)', () => {
      assert.equal(cart.removeItem('APPLE'), false);
      assert.equal(cart.getItemCount(), 3);
    });

    it('rejects a non-string name with TypeError', () => {
      assert.throws(() => cart.removeItem(undefined), TypeError);
      assert.throws(() => cart.removeItem(1), TypeError);
      assert.equal(cart.getItemCount(), 3);
    });
  });

  describe('getTotal', () => {
    it('bug 3: returns 0 for an empty cart instead of reading past the end', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 3: sums price × quantity across every item without throwing', () => {
      cart.addItem('apple', 1.25, 4);
      cart.addItem('banana', 2, 3);
      assert.equal(cart.getTotal(), 11);
    });

    it('returns the line total for a single item', () => {
      cart.addItem('apple', 3, 3);
      assert.equal(cart.getTotal(), 9);
    });

    it('bug 4: subtracts the discount from the total', () => {
      cart.addItem('widget', 50, 2);
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 90);
    });

    it('bug 4: never returns more than the undiscounted total', () => {
      cart.addItem('widget', 40, 1);
      cart.applyDiscount(25);
      assert.ok(cart.getTotal() < 40, `expected < 40, got ${cart.getTotal()}`);
      assert.equal(cart.getTotal(), 30);
    });

    it('returns the undiscounted total when the discount is 0', () => {
      cart.addItem('widget', 50, 2);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 100);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('widget', 50, 2);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('does not change cart state when called repeatedly', () => {
      cart.addItem('widget', 5, 2);
      cart.applyDiscount(20);
      const before = structuredClone(cart.items);
      assert.equal(cart.getTotal(), 8);
      assert.equal(cart.getTotal(), 8);
      assert.deepEqual(cart.items, before);
      assert.equal(cart.discount, 20);
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid percentage', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the 0 and 100 boundaries', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('accepts a fractional percentage', () => {
      cart.addItem('widget', 200, 1);
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 175);
    });

    it('bug 5: rejects a discount above 100 with RangeError', () => {
      assert.throws(() => cart.applyDiscount(101), RangeError);
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: rejects a negative discount with RangeError', () => {
      assert.throws(() => cart.applyDiscount(-1), RangeError);
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: keeps the previous valid discount when an invalid one is rejected', () => {
      cart.addItem('widget', 100, 1);
      cart.applyDiscount(20);
      assert.throws(() => cart.applyDiscount(150), RangeError);
      assert.equal(cart.discount, 20);
      assert.equal(cart.getTotal(), 80);
    });

    it('rejects Infinity with RangeError', () => {
      assert.throws(() => cart.applyDiscount(Infinity), RangeError);
      assert.throws(() => cart.applyDiscount(-Infinity), RangeError);
    });

    for (const [label, badValue] of [
      ['NaN', NaN],
      ['a numeric string', '10'],
      ['null', null],
      ['undefined', undefined],
    ]) {
      it(`rejects ${label} with TypeError`, () => {
        assert.throws(() => cart.applyDiscount(badValue), TypeError);
        assert.equal(cart.discount, 0);
      });
    }

    it('replaces the previous discount instead of stacking', () => {
      cart.addItem('widget', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(30);
      assert.equal(cart.getTotal(), 70);
    });
  });

  describe('getItemCount', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getItemCount(), 0);
    });

    it('counts distinct line items, not summed quantity', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 2);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases after a removal and ignores failed adds', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      assert.throws(() => cart.addItem('cherry', -1, 1), RangeError);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });
  });
});

