      cart.addItem('Apple', 1, 1);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('bug 1: rejects a negative price with RangeError and leaves the cart empty', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), {
        name: 'RangeError',
