const MIN_DISCOUNT_PERCENT = 0;
const MAX_DISCOUNT_PERCENT = 100;

// Describes a rejected value by type so error messages never call String()
// on arbitrary input (Symbols and null-prototype objects throw when stringified).
function typeLabel(value) {
  return value === null ? 'null' : typeof value;
}

function assertNumber(value, label) {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    const received = Number.isNaN(value) ? 'NaN' : typeLabel(value);
    throw new TypeError(`${label} must be a number, received ${received}`);
  }
}

function assertName(name) {
  if (typeof name !== 'string') {
    throw new TypeError(`name must be a string, received ${typeLabel(name)}`);
  }
  if (name.trim() === '') {
    throw new RangeError('name must not be empty or whitespace-only');
  }
}

/**
 * In-memory shopping cart. Line items are unique by name (case-sensitive).
 */
class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  /**
   * Adds a line item, or increases the quantity of the line with the same name.
   * A repeated name keeps the unit price it was first added with.
   *
   * @param {string} name non-blank item name
   * @param {number} price finite unit price, 0 or more
   * @param {number} [quantity=1] positive safe integer
   * @throws {TypeError} if name is not a string, or price/quantity is not a number
   * @throws {RangeError} if name is blank, price is negative or non-finite,
   *   quantity is not a positive integer, or the merged quantity is unsafe
   */
  addItem(name, price, quantity = 1) {
    assertName(name);
    assertNumber(price, 'price');
    if (!Number.isFinite(price) || price < 0) {
      throw new RangeError(`price must be a finite number >= 0, received ${price}`);
    }
    assertNumber(quantity, 'quantity');
    if (!Number.isSafeInteger(quantity) || quantity < 1) {
      throw new RangeError(`quantity must be a positive integer, received ${quantity}`);
    }

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      const merged = existing.quantity + quantity;
      if (!Number.isSafeInteger(merged)) {
        throw new RangeError(
          `quantity for "${name}" would exceed ${Number.MAX_SAFE_INTEGER}`,
        );
      }
      existing.quantity = merged;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes the whole line with the given name.
   *
   * @param {string} name
   * @returns {boolean} true if a line was removed, false if no line had that name
   * @throws {TypeError} if name is not a string
   */
  removeItem(name) {
    if (typeof name !== 'string') {
      throw new TypeError(`name must be a string, received ${typeLabel(name)}`);
    }
    const countBefore = this.items.length;
    this.items = this.items.filter(i => i.name !== name);
    return this.items.length < countBefore;
  }

  /**
   * @returns {number} sum of price × quantity with the discount subtracted.
   *   Not rounded; format to the currency's precision at display time.
   */
  getTotal() {
    let total = 0;
    for (const item of this.items) {
      total += item.price * item.quantity;
    }
    return total - (total * this.discount / 100);
  }

  /**
   * Sets the percentage discount used by getTotal, replacing any previous one.
   * An invalid value leaves the current discount unchanged.
   *
   * @param {number} percent 0 to 100 inclusive
   * @throws {TypeError} if percent is not a number or is NaN
   * @throws {RangeError} if percent is outside 0–100
   */
  applyDiscount(percent) {
    assertNumber(percent, 'discount');
    if (percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT) {
      throw new RangeError(
        `discount must be between ${MIN_DISCOUNT_PERCENT} and ${MAX_DISCOUNT_PERCENT}, received ${percent}`,
      );
    }
    this.discount = percent;
  }

  /**
   * @returns {number} number of distinct line items, not the summed quantity
   */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

