const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

function assertClose(actual, expected, epsilon = 1e-9) {
  assert.ok(
    Math.abs(actual - expected) < epsilon,
    `expected ${actual} to be within ${epsilon} of ${expected}`,
  );
}

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('unicode and unusual names', () => {
    it('stores and removes non-ASCII names', () => {
      cart.addItem('café', 3, 1);
      cart.addItem('苹果', 2, 2);
      cart.addItem('🍎', 1, 3);
      assert.equal(cart.getItemCount(), 3);
      assert.equal(cart.removeItem('苹果'), true);
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['café', '🍎'],
      );
    });

    it('treats accented and unaccented names as different items', () => {
      cart.addItem('café', 3, 1);
      cart.addItem('cafe', 3, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('compares names by exact code units, without Unicode normalization', () => {
      const composed = 'café';
      const decomposed = 'café';
      cart.addItem(composed, 3, 1);
      cart.addItem(decomposed, 3, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('keeps surrounding whitespace, so " apple " and "apple" are distinct', () => {
      cart.addItem(' apple ', 1, 1);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
      assert.equal(cart.removeItem('apple'), true);
      assert.equal(cart.items[0].name, ' apple ');
    });

    it('accepts a very long name', () => {
      const longName = 'x'.repeat(5000);
      cart.addItem(longName, 1, 1);
      assert.equal(cart.items[0].name.length, 5000);
      assert.equal(cart.removeItem(longName), true);
    });

    it('rejects names made only of tabs and newlines', () => {
      assert.throws(() => cart.addItem('\t\n ', 1, 1), RangeError);
    });

    it('removeItem returns false for an empty-string name', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem(''), false);
      assert.equal(cart.getItemCount(), 1);
    });
  });

  describe('unusual argument types', () => {
    it('raises TypeError, not a stringification crash, for Symbol arguments', () => {
      assert.throws(() => cart.addItem(Symbol('n'), 1, 1), {
        name: 'TypeError',
        message: /received symbol/,
      });
      assert.throws(() => cart.addItem('apple', Symbol('p'), 1), {
        name: 'TypeError',
        message: /price must be a number, received symbol/,
      });
      assert.throws(() => cart.applyDiscount(Symbol('d')), {
        name: 'TypeError',
        message: /received symbol/,
      });
    });

    it('raises TypeError for a null-prototype object price', () => {
      assert.throws(() => cart.addItem('apple', Object.create(null), 1), {
        name: 'TypeError',
        message: /received object/,
      });
    });

    it('rejects boxed Number objects', () => {
      // eslint-disable-next-line no-new-wrappers
      assert.throws(() => cart.addItem('apple', new Number(5), 1), TypeError);
      // eslint-disable-next-line no-new-wrappers
      assert.throws(() => cart.applyDiscount(new Number(5)), TypeError);
    });

    it('reports NaN by name in the error message', () => {
      assert.throws(() => cart.addItem('apple', NaN, 1), {
        message: 'price must be a number, received NaN',
      });
    });

    it('includes the rejected value in range error messages', () => {
      assert.throws(() => cart.addItem('apple', -3.5, 1), {
        message: /received -3\.5/,
      });
      assert.throws(() => cart.applyDiscount(120), {
        message: 'discount must be between 0 and 100, received 120',
      });
    });
  });

  describe('numeric boundaries', () => {
    it('accepts quantity at Number.MAX_SAFE_INTEGER and rejects one above it', () => {
      cart.addItem('bulk', 0, Number.MAX_SAFE_INTEGER);
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
      assert.throws(
        () => new ShoppingCart().addItem('bulk', 0, Number.MAX_SAFE_INTEGER + 1),
        RangeError,
      );
    });

    it('rejects a merge that would push quantity past MAX_SAFE_INTEGER and keeps the old quantity', () => {
      cart.addItem('bulk', 1, Number.MAX_SAFE_INTEGER);
      assert.throws(() => cart.addItem('bulk', 1, 1), RangeError);
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('accepts the smallest positive quantity of 1', () => {
      cart.addItem('apple', 2, 1);
      assert.equal(cart.getTotal(), 2);
    });

    it('accepts discounts just inside the range and rejects values just outside', () => {
      cart.applyDiscount(Number.EPSILON);
      assert.equal(cart.discount, Number.EPSILON);
      cart.applyDiscount(99.999);
      assert.equal(cart.discount, 99.999);
      assert.throws(() => cart.applyDiscount(-Number.EPSILON), RangeError);
      assert.throws(() => cart.applyDiscount(100 + 1e-10), RangeError);
      assert.equal(cart.discount, 99.999);
    });

    it('computes fractional-cent prices within floating-point tolerance', () => {
      cart.addItem('a', 0.1, 1);
      cart.addItem('b', 0.2, 1);
      assertClose(cart.getTotal(), 0.3);
    });

    it('computes a discounted total with a repeating decimal', () => {
      cart.addItem('a', 10, 1);
      cart.applyDiscount(100 / 3);
      assertClose(cart.getTotal(), 20 / 3);
    });

    it('returns 0 for a cart of only free items even with a discount', () => {
      cart.addItem('sticker', 0, 10);
      cart.applyDiscount(50);
      assert.equal(cart.getTotal(), 0);
    });
  });

  describe('state isolation and side effects', () => {
    it('keeps items and discounts separate between cart instances', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 1, 1);
      cart.applyDiscount(50);
      assert.deepEqual(other.items, []);
      assert.equal(other.discount, 0);
      assert.notEqual(cart.items, other.items);
    });

    it('does not reorder remaining items after a removal', () => {
      for (const name of ['a', 'b', 'c', 'd', 'e']) cart.addItem(name, 1, 1);
      cart.removeItem('c');
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['a', 'b', 'd', 'e'],
      );
    });

    it('a rejected merge does not change the existing line at all', () => {
      cart.addItem('apple', 2, 3);
      const before = structuredClone(cart.items);
      assert.throws(() => cart.addItem('apple', -2, 1), RangeError);
      assert.throws(() => cart.addItem('apple', 2, 0), RangeError);
      assert.throws(() => cart.addItem('apple', 2, 'x'), TypeError);
      assert.deepEqual(cart.items, before);
    });
  });

  describe('stress and concurrency', () => {
    it('handles 10,000 distinct line items', () => {
      const count = 10_000;
      for (let i = 0; i < count; i++) cart.addItem(`item-${i}`, 1, 2);
      assert.equal(cart.getItemCount(), count);
      assert.equal(cart.getTotal(), count * 2);
      for (let i = 0; i < count; i += 2) cart.removeItem(`item-${i}`);
      assert.equal(cart.getItemCount(), count / 2);
      assert.equal(cart.getTotal(), count);
    });

    it('merges a burst of 1,000 adds of the same item into one line', () => {
      for (let i = 0; i < 1000; i++) cart.addItem('apple', 0.5, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 1000);
      assert.equal(cart.getTotal(), 500);
    });

    it('concurrent async callers adding and removing produce a consistent cart', async () => {
      const addLater = (name, qty) =>
        new Promise((resolve) => {
          setImmediate(() => {
            cart.addItem(name, 1, qty);
            resolve();
          });
        });

      await Promise.all([
        ...Array.from({ length: 50 }, () => addLater('shared', 2)),
        ...Array.from({ length: 50 }, (_, i) => addLater(`solo-${i}`, 1)),
      ]);
      await Promise.all(
        Array.from({ length: 25 }, (_, i) =>
          Promise.resolve().then(() => cart.removeItem(`solo-${i}`)),
        ),
      );

      assert.equal(cart.items.find((i) => i.name === 'shared').quantity, 100);
      assert.equal(cart.getItemCount(), 1 + 25);
      assert.equal(cart.getTotal(), 100 + 25);
    });
  });
});

