    it('keeps items and discounts separate between cart instances', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 1, 1);
      cart.applyDiscount(50);
      assert.deepEqual(other.items, []);
      assert.equal(other.discount, 0);
      assert.notEqual(cart.items, other.items);
    });

    it('does not reorder remaining items after a removal', () => {
      for (const name of ['a', 'b', 'c', 'd', 'e']) cart.addItem(name, 1, 1);
      cart.removeItem('c');
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['a', 'b', 'd', 'e'],
      );
    });

    it('a rejected merge does not change the existing line at all', () => {
      cart.addItem('apple', 2, 3);
      const before = structuredClone(cart.items);
      assert.throws(() => cart.addItem('apple', -2, 1), RangeError);
      assert.throws(() => cart.addItem('apple', 2, 0), RangeError);
      assert.throws(() => cart.addItem('apple', 2, 'x'), TypeError);
      assert.deepEqual(cart.items, before);
    });
  });

  describe('stress and concurrency', () => {
    it('handles 10,000 distinct line items', () => {
      const count = 10_000;
      for (let i = 0; i < count; i++) cart.addItem(`item-${i}`, 1, 2);
      assert.equal(cart.getItemCount(), count);
      assert.equal(cart.getTotal(), count * 2);
      for (let i = 0; i < count; i += 2) cart.removeItem(`item-${i}`);
      assert.equal(cart.getItemCount(), count / 2);
      assert.equal(cart.getTotal(), count);
    });

    it('merges a burst of 1,000 adds of the same item into one line', () => {
      for (let i = 0; i < 1000; i++) cart.addItem('apple', 0.5, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 1000);
      assert.equal(cart.getTotal(), 500);
    });

    it('concurrent async callers adding and removing produce a consistent cart', async () => {
      const addLater = (name, qty) =>
        new Promise((resolve) => {
          setImmediate(() => {
            cart.addItem(name, 1, qty);
            resolve();
          });
        });

      await Promise.all([
        ...Array.from({ length: 50 }, () => addLater('shared', 2)),
        ...Array.from({ length: 50 }, (_, i) => addLater(`solo-${i}`, 1)),
      ]);
      await Promise.all(
        Array.from({ length: 25 }, (_, i) =>
          Promise.resolve().then(() => cart.removeItem(`solo-${i}`)),
        ),
      );

      assert.equal(cart.items.find((i) => i.name === 'shared').quantity, 100);
      assert.equal(cart.getItemCount(), 1 + 25);
      assert.equal(cart.getTotal(), 100 + 25);
    });
  });
});

