const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart end-to-end flows', () => {
  it('runs a full checkout: add, merge, remove, discount, total', () => {
    const cart = new ShoppingCart();
    cart.addItem('shirt', 20, 2);
    cart.addItem('socks', 5, 3);
    cart.addItem('hat', 15, 1);
    cart.addItem('socks', 5, 1);

    assert.equal(cart.getItemCount(), 3);
    assert.equal(cart.getTotal(), 40 + 20 + 15);

    assert.equal(cart.removeItem('hat'), true);
    assert.equal(cart.getTotal(), 60);

    cart.applyDiscount(25);
    assert.equal(cart.getTotal(), 45);
    assert.equal(cart.getItemCount(), 2);
  });

  it('applies a discount set before any items were added', () => {
    const cart = new ShoppingCart();
    cart.applyDiscount(50);
    assert.equal(cart.getTotal(), 0);
    cart.addItem('book', 30, 1);
    assert.equal(cart.getTotal(), 15);
  });

  it('returns 0 after every item is removed, even with a discount', () => {
    const cart = new ShoppingCart();
    cart.addItem('a', 10, 1);
    cart.addItem('b', 20, 1);
    cart.applyDiscount(10);
    cart.removeItem('a');
    cart.removeItem('b');
    assert.equal(cart.getItemCount(), 0);
    assert.equal(cart.getTotal(), 0);
  });

  it('recovers from rejected operations mid-flow without corrupting state', () => {
    const cart = new ShoppingCart();
    cart.addItem('laptop', 1000, 1);
    cart.applyDiscount(10);

    assert.throws(() => cart.addItem('mouse', -25, 1), RangeError);
    assert.throws(() => cart.addItem('laptop', 1000, -1), RangeError);
    assert.throws(() => cart.applyDiscount(110), RangeError);
    assert.throws(() => cart.applyDiscount(-5), RangeError);
    assert.equal(cart.removeItem('tablet'), false);

    assert.deepEqual(cart.items, [{ name: 'laptop', price: 1000, quantity: 1 }]);
    assert.equal(cart.discount, 10);
    assert.equal(cart.getTotal(), 900);
  });

  it('re-adding a removed item starts a fresh line at the new price', () => {
    const cart = new ShoppingCart();
    cart.addItem('coffee', 4, 2);
    cart.removeItem('coffee');
    cart.addItem('coffee', 5, 1);
    assert.deepEqual(cart.items, [{ name: 'coffee', price: 5, quantity: 1 }]);
    assert.equal(cart.getTotal(), 5);
  });

  it('changing the discount repeatedly always uses the latest value', () => {
    const cart = new ShoppingCart();
    cart.addItem('tv', 500, 1);
    const totals = [0, 10, 100, 20].map((percent) => {
      cart.applyDiscount(percent);
      return cart.getTotal();
    });
    assert.deepEqual(totals, [500, 450, 0, 400]);
  });
});

