fs.mkdirSync(path.join(work, 'src'), { recursive: true });
fs.cpSync(path.join(root, 'tests'), path.join(work, 'tests'), { recursive: true });

const mutations = {
  'bug 1 (negative price/quantity allowed)': [
    ['price < 0', 'false'],
    ['quantity < 1', 'false'],
  ],
  'bug 2a (= instead of !==)': [['i.name !== name', 'i.name = name']],
  'bug 2b (missing item not reported)': [['return this.items.length < countBefore;', 'return;']],
  'bug 3 (<= off-by-one)': [[
    'for (const item of this.items) {\n      total += item.price * item.quantity;\n    }',
    'for (let i = 0; i <= this.items.length; i++) {\n      total += this.items[i].price * this.items[i].quantity;\n    }',
  ]],
  'bug 4 (discount added)': [['total - (total', 'total + (total']],
  'bug 5 (no range check)': [['percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT', 'false']],
};

for (const [label, edits] of Object.entries(mutations)) {
  let src = original;
  for (const [from, to] of edits) {
    if (!src.includes(from)) throw new Error(`mutation "${label}" target not found: ${from}`);
    src = src.replace(from, to);
  }
  fs.writeFileSync(path.join(work, 'src/cart.js'), src);
  let out = '';
  try {
    out = execFileSync(process.execPath, ['--test', '--test-reporter=spec', 'tests/cart.test.js'], { cwd: work, encoding: 'utf8', stdio: 'pipe' });
